package dev.eugheist.tc4modern;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import thaumcraft.api.aspects.Aspect;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class SinisterStoneAudit {
 static final BlockPos POS=FocalAudit.BASE.offset(56,3,64);static int ticks;static volatile boolean prepared;
 static void check(boolean b,String s){if(!b)throw new IllegalStateException("TC4_SINSTONE FAIL "+s);System.out.println("TC4_SINSTONE PASS "+s);}
 static void prepare(ServerPlayer p){var l=p.serverLevel();p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.getAbilities().flying=true;p.onUpdateAbilities();p.removeAllEffects();p.getInventory().clearContent();for(var cat:thaumcraft.api.research.ResearchCategories.researchCategories.values())for(var r:cat.research.values())DevCommands.grant(p.getPersistentData(),r.key,new HashSet<>());ThaumometerItem.sync(p,"");for(int x=-4;x<=4;x++)for(int z=-7;z<=4;z++)for(int y=-3;y<=3;y++)l.setBlock(POS.offset(x,y,z),y==-3?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),2);
  l.setBlock(POS,TC4Modern.AURA_NODE.get().defaultBlockState(),3);var node=(AuraNodeEntity)l.getBlockEntity(POS);node.nodeType=thaumcraft.api.nodes.NodeType.DARK;node.reservoir.aspectsBase.add(Aspect.AIR,20);node.reservoir.aspects.add(Aspect.AIR,20);node.changed();
  var r=InfusionItemRecipes.all().stream().filter(v->v.key().equals("SinStone")).findFirst().orElseThrow();var components=r.components().stream().map(c->new ItemStack(c.get())).toList();check(r.central().get()==Items.FLINT&&r.aspects().visSize()==32&&r.instability()==5&&InfusionItemRecipes.match(components,new ItemStack(Items.FLINT),Set.of("SINSTONE"))==r&&InfusionItemRecipes.match(components,new ItemStack(Items.FLINT),Set.of())==null,"original flint infusion and research gate");check(WarpGear.contribution(new ItemStack(SinisterStone.ITEM.get()),p)==1,"held stone contributes original1warp");p.connection.teleport(POS.getX()+.5,POS.getY()-1.12,POS.getZ()-5,0,0);p.getInventory().setItem(0,new ItemStack(SinisterStone.ITEM.get()));p.getInventory().selected=0;prepared=true;
 }
 static void checkClient(net.minecraft.client.Minecraft mc){check(prepared,"server setup complete");check(SinisterStoneClient.NODES.containsKey(new SinisterStoneClient.Node(mc.level.dimension(),POS)),"natural dark-node50tick discovery reaches stone cache");var player=mc.player;float old=player.getYRot(),pitch=player.getXRot();player.setYRot(0);player.setXRot(0);SinisterStoneClient.update(player);check(SinisterStoneClient.active,"look toward dark node activates stone");player.setYRot(180);SinisterStoneClient.update(player);check(!SinisterStoneClient.active,"look away deactivates stone");player.setYRot(0);check(SinisterStoneClient.withinCone(player,player.blockPosition().south(255).above())&&!SinisterStoneClient.withinCone(player,player.blockPosition().south(257).above()),"original cone capped at256projected blocks");player.setYRot(30);check(!SinisterStoneClient.withinCone(player,POS),"outside original.33radian half-aperture excluded");player.setYRot(0);
  var saved=new HashMap<>(SinisterStoneClient.NODES);SinisterStoneClient.NODES.clear();SinisterStoneClient.NODES.put(new SinisterStoneClient.Node(net.minecraft.world.level.Level.NETHER,POS),System.currentTimeMillis());SinisterStoneClient.update(player);check(!SinisterStoneClient.active,"other dimension ignored");SinisterStoneClient.NODES.clear();SinisterStoneClient.NODES.put(new SinisterStoneClient.Node(mc.level.dimension(),POS),System.currentTimeMillis()-11000);SinisterStoneClient.update(player);check(SinisterStoneClient.active&&SinisterStoneClient.NODES.isEmpty(),"original expired node still activates during cleanup frame");SinisterStoneClient.update(player);check(!SinisterStoneClient.active,"expired cached node disappears next frame");SinisterStoneClient.NODES.putAll(saved);player.setYRot(old);player.setXRot(pitch);
 }
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.sinStoneAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)server.execute(()->prepare(server.getPlayerList().getPlayer(id)));if(ticks==155){mc.player.getInventory().selected=0;checkClient(mc);server.execute(()->{var l=server.overworld();for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)l.setBlock(POS.offset(x,y,-2),Blocks.STONE.defaultBlockState(),3);});}if(ticks==170){SinisterStoneClient.update(mc.player);check(SinisterStoneClient.active,"original detection passes through opaque wall");var model=mc.getItemRenderer().getModel(mc.player.getMainHandItem(),mc.level,mc.player,0);check(model.getQuads(null,null,net.minecraft.util.RandomSource.create()).stream().anyMatch(q->q.getSprite().contents().name().getPath().equals("items/sinister_stone_active")),"actual held item resolves active texture");LiquidDeathAudit.shot(mc,"sinister-stone-active.png");server.execute(()->{var p=server.getPlayerList().getPlayer(id);p.connection.teleport(p.getX(),p.getY(),p.getZ(),180,0);});}if(ticks==185){SinisterStoneClient.update(mc.player);check(!SinisterStoneClient.active,"turned player sees inactive stone");LiquidDeathAudit.shot(mc,"sinister-stone-inactive.png");var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty());book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch("SINSTONE"),0);mc.setScreen(book);}if(ticks==195)LiquidDeathAudit.shot(mc,"sinister-stone-book.png");if(ticks==205)mc.stop();}
}
